            var expected=generated.OfType<AnimatorOverrideController>().Single();var runtime=basis.runtimeAnimatorController;while(runtime is AnimatorOverrideController nested)runtime=nested.runtimeAnimatorController;if(runtime is not AnimatorController controller)throw new InvalidOperationException("Actual original native Flight graph required.");var keys=MotionClips(ControllerStates(controller.layers[0].stateMachine).Single(state=>state.name=="Flight").motion).Distinct().ToArray();if(keys.Length!=5)throw new InvalidOperationException("Five measured source leaves required.");var validationKeys=keys.ToList();if(safeMounted){var catalog=AssetDatabase.LoadAssetAtPath<DragonSpeciesCatalog>("Assets/TruckDragonKingdom/Settings/DragonSpeciesCatalog.asset");if(!catalog.TryGet(species,out var definition))throw new InvalidOperationException("Actual source species required.");foreach(var action in MountedPostureActions(definition)){if(!definition.TryGetAnimation(action,out var mapped))throw new InvalidOperationException("Actual mounted action required: "+action);validationKeys.Add(mapped.clip);}}var sources=AssetDatabase.GetDependencies(ActorPath(species),true).Concat(AssetDatabase.GetDependencies(FlightBaseControllerPath(species),true)).Concat(FlightRecipeInputs).Where(path=>path.StartsWith("Assets/",StringComparison.Ordinal)&&!IsSavedFlightAsset(path)&&File.Exists(path)).SelectMany(path=>File.Exists(path+".meta")?new[]{path,path+".meta"}:new[]{path}).Distinct().ToDictionary(path=>path,Hash);return new SavedFlightPlan{species=species,flap=species=="dragon-inferno"?.25f:.5f,basis=basis,expected=expected,temporary=generated.ToList(),keys=keys,validationKeys=validationKeys.Distinct().ToArray(),safeMounted=safeMounted,sources=sources};
        }
