        static void AssertNonFlightMappings(AnimatorOverrideController basis,AnimatorOverrideController candidate,AnimationClip[] normalKeys)
        {var entries=new List<KeyValuePair<AnimationClip,AnimationClip>>();basis.GetOverrides(entries);foreach(var pair in entries)if(!normalKeys.Contains(pair.Key)){var expected=pair.Value!=null?pair.Value:pair.Key;var actual=candidate[pair.Key]!=null?candidate[pair.Key]:pair.Key;if(actual!=expected)throw new InvalidOperationException("Saved normal flight changed original non-flight/action mapping: "+pair.Key.name);}}
